import numpy as np
from sklearn.metrics import median_absolute_error
from sklearn.utils.stats import _weighted_percentile


def weekly_kpi(actual, forecast, demand_weight):
    \"\"\"Demand-weighted median absolute forecast error for one week (lower is better).\"\"\"
    actual = np.asarray(actual)
    forecast = np.asarray(forecast)
    errors = np.abs(forecast - actual)
    if demand_weight is None:
        return float(np.median(errors))

    demand_weight = np.asarray(demand_weight)
    return float(_weighted_percentile(errors, sample_weight=demand_weight, average=False))

